	if oum_is_installed; then
		installed='ÑƒÑÑ‚Ð°Ð½Ð¾Ð²Ð»ÐµÐ½'
	else
		installed='Ð½Ðµ ÑƒÑÑ‚Ð°Ð½Ð¾Ð²Ð»ÐµÐ½'
	fi

	printf '\n====================================================\n'
	printf '       OUM â€” OpenWrt Ultimate Manager\n'
	printf '====================================================\n'
	printf ' Ð¡Ð±Ð¾Ñ€ÐºÐ°: %s Â· Ð¡Ð¾ÑÑ‚Ð¾ÑÐ½Ð¸Ðµ: %s\n' "$OUM_INSTALLER_VERSION" "$installed"
	printf '\n'
	printf ' 1) Ð£ÑÑ‚Ð°Ð½Ð¾Ð²Ð¸Ñ‚ÑŒ / Ð¾Ð±Ð½Ð¾Ð²Ð¸Ñ‚ÑŒ OUM\n'
	printf ' 2) ÐŸÐµÑ€Ð²Ñ‹Ð¹ Ð·Ð°Ð¿ÑƒÑÐº\n'
